package com.thang.user.service.user;
import com.thang.user.model.entity.*;import com.thang.user.model.dto.TokenUserResponse;import com.thang.user.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import org.springframework.scheduling.annotation.Scheduled;import java.time.LocalDateTime;import java.security.SecureRandom;import java.util.*;
@Service @RequiredArgsConstructor
public class AuthMfaService {
 private final IUserRepository users;private final AuthMfaDeviceRepository devices;private final AuthMfaChallengeRepository challenges;private final AuthMfaBackupRepository backups;
 private final MfaChallengeIssuer issuer;private final SessionTokenCipher cipher;private final PasswordEncoder passwords;private final TokenService tokens;private final SessionService sessions;private final LoginAuditService history;private final RateLimitService limits;private final AdminAccountAuditRepository audit;
 public record Status(boolean enabled,long backupCodes){} public record Setup(String secret,String uri,long expiresAt){} public record Verification(TokenUserResponse tokens,long retryAfter){}
 public void require(User user){if(devices.findById(user.getUserId()).map(AuthMfaDevice::isEnabled).orElse(false))throw new MfaRequiredException(issuer.issue(user));}
 @Transactional(readOnly=true) public Status status(String userId){return new Status(devices.findById(userId).map(AuthMfaDevice::isEnabled).orElse(false),backups.countByUserId(userId));}
 @Transactional public Setup setup(String userId,String password){User user=owner(userId);password(user,password);var device=devices.lock(userId).orElseGet(AuthMfaDevice::new);if(device.isEnabled())throw conflict("Xác thực hai bước đã bật");String secret=TotpCodes.secret();device.setUserId(userId);device.setPendingSecret(cipher.encrypt(userId,secret));device.setSetupExpiresAt(System.currentTimeMillis()+600000);devices.save(device);String label=java.net.URLEncoder.encode("Nihongo:"+user.getEmail(),java.nio.charset.StandardCharsets.UTF_8);return new Setup(secret,"otpauth://totp/"+label+"?secret="+secret+"&issuer=Nihongo&algorithm=SHA1&digits=6&period=30",device.getSetupExpiresAt());}
 @Transactional public List<String> enable(String userId,String code){owner(userId);var device=devices.lock(userId).orElseThrow(()->conflict("Tạo mã thiết lập trước"));if(device.isEnabled()||device.getPendingSecret()==null||device.getSetupExpiresAt()<System.currentTimeMillis())throw conflict("Thiết lập đã hết hạn hoặc đã bật");long counter=TotpCodes.verify(cipher.decrypt(userId,device.getPendingSecret()),code,System.currentTimeMillis(),-1);if(counter<0)throw bad("Mã xác thực không hợp lệ");device.setEncryptedSecret(device.getPendingSecret());device.setPendingSecret(null);device.setEnabled(true);device.setLastCounter(counter);sessions.removeSession(userId);audit(userId,"MFA_ENABLE");return generateBackups(userId);}
 @Transactional public void disable(String userId,String password,String code){User user=owner(userId);password(user,password);var device=devices.lock(userId).orElseThrow(()->bad("Chưa bật xác thực hai bước"));if(!device.isEnabled()||!consumeCode(device,code))throw bad("Mã xác thực không hợp lệ hoặc đã sử dụng");device.setEnabled(false);device.setEncryptedSecret(null);device.setPendingSecret(null);backups.clear(userId);sessions.removeSession(userId);audit(userId,"MFA_DISABLE");}
 @Transactional public List<String> newBackups(String userId,String password,String code){User user=owner(userId);password(user,password);var device=devices.lock(userId).orElseThrow(()->bad("Chưa bật xác thực hai bước"));if(!device.isEnabled()||!consumeCode(device,code))throw bad("Mã xác thực không hợp lệ hoặc đã sử dụng");audit(userId,"MFA_BACKUP_ROTATE");return generateBackups(userId);}
 @Transactional public Verification verify(String challenge,String code){
  if(challenge==null||challenge.length()>100)return new Verification(null,0);String id=PasswordSetupService.hash(challenge);var reference=challenges.findById(id).orElse(null);if(reference==null)return new Verification(null,0);
  User user=users.lockById(reference.getUserId()).orElse(null);var pending=challenges.lock(id).orElse(null);if(pending==null)return new Verification(null,0);
  if(user==null||!user.isActive()||pending.getExpiresAt()<System.currentTimeMillis()||pending.getAttempts()>=5||!pending.getRole().equals(user.getRoleName())||!pending.getCredentialFingerprint().equals(PasswordSetupService.hash(user.getPassword()==null?"":user.getPassword()))){challenges.delete(pending);return new Verification(null,0);}
  var limit=limits.consume(new RateLimitService.Limit("MFA_VERIFY_ACCOUNT",user.getUserId()));if(!limit.allowed())return new Verification(null,limit.retryAfter());
  var device=devices.lock(user.getUserId()).orElse(null);if(device==null||!device.isEnabled()||!consumeCode(device,code)){pending.setAttempts(pending.getAttempts()+1);if(pending.getAttempts()>=5)challenges.delete(pending);return new Verification(null,0);}
  challenges.delete(pending);user.setLastLogin(LocalDateTime.now());user.setDateModified(LocalDateTime.now());var result=tokens.generateToken(user,UUID.randomUUID().toString());history.record(user,"MFA");return new Verification(result,0);
 }
 @Transactional public void cancel(String challenge){if(challenge!=null&&challenge.length()<=100)challenges.deleteById(PasswordSetupService.hash(challenge));}
 private boolean consumeCode(AuthMfaDevice device,String input){if(input==null)return false;String code=input.trim();long counter=TotpCodes.verify(cipher.decrypt(device.getUserId(),device.getEncryptedSecret()),code,System.currentTimeMillis(),device.getLastCounter());if(counter>=0){device.setLastCounter(counter);return true;}String backup=code.replace("-","").toUpperCase(Locale.ROOT);if(!backup.matches("[A-F0-9]{32}"))return false;String id=PasswordSetupService.hash(device.getUserId()+":"+backup);var row=backups.findById(id).orElse(null);if(row==null||!device.getUserId().equals(row.getUserId()))return false;backups.delete(row);return true;}
 private List<String> generateBackups(String userId){backups.clear(userId);List<String> result=new ArrayList<>();for(int i=0;i<10;i++){byte[] bytes=new byte[16];new SecureRandom().nextBytes(bytes);String plain=HexFormat.of().withUpperCase().formatHex(bytes);var row=new AuthMfaBackup();row.setId(PasswordSetupService.hash(userId+":"+plain));row.setUserId(userId);backups.save(row);result.add(String.join("-",plain.substring(0,8),plain.substring(8,16),plain.substring(16,24),plain.substring(24,32)));}return result;}
 private User owner(String userId){var user=users.lockById(userId).orElseThrow(()->bad("Không tìm thấy tài khoản"));if(!user.isActive())throw bad("Tài khoản không hoạt động");return user;}
 private void password(User user,String value){if(value==null||value.length()>100||user.getPassword()==null||!passwords.matches(value,user.getPassword()))throw bad("Mật khẩu hiện tại không đúng");}
 private void audit(String userId,String action){var row=new AdminAccountAudit();row.setActorUserId(userId);row.setTargetUserId(userId);row.setAction(action);row.setNewValue("Security setting updated");row.setCreatedAt(LocalDateTime.now());audit.save(row);}
 @Scheduled(fixedDelay=300000) @Transactional public void cleanup(){challenges.cleanup(System.currentTimeMillis());}
 private static ResponseStatusException bad(String text){return new ResponseStatusException(HttpStatus.BAD_REQUEST,text);}private static ResponseStatusException conflict(String text){return new ResponseStatusException(HttpStatus.CONFLICT,text);}
}
